import{z as c,x as A,o as r,c as n,q as l,j as o,D as e,d as t,s as i,S as p}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"CUDA 执行模型的深入","description":"","frontmatter":{"title":"CUDA 执行模型的深入","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-execution-model-deep.md","filePath":"cs/gpu-execution-model-deep.md","lastUpdated":1791063341000}'),s={name:"cs/gpu-execution-model-deep.md"};function B(d,a,m,h,u,D){const E=A("Mermaid");return r(),n("div",null,[a[2]||(a[2]=l('<h1 id="cuda-执行模型的深入" tabindex="-1">CUDA 执行模型的深入 <a class="header-anchor" href="#cuda-执行模型的深入" aria-label="Permalink to &quot;CUDA 执行模型的深入&quot;">​</a></h1><div class="epigraph"><p>线程是你写的语法，warp 才是硬件执行的语法；两套语法之间的翻译合同，就是 GPU 编程的第一笔税。</p><footer>—— 据 NVIDIA CUDA C++ Programming Guide「Hardware Implementation」章与 Lindholm et al., IEEE Micro, 2008 整理</footer></div><p><a href="/cs/formal-verification-sel4">上一课</a>把安全进阶封了口：细化把规格接到 C，假设之外仍是工程；密码、利用与系统防御一族到此收束。本课是「GPU 编程深入」的第一课，转向另一端的机器。本栏主干已经给过两块底子：<a href="/cs/gpu-simt">SIMT</a> 讲了 warp 共享 PC、切 warp 藏延迟的画面，<a href="/cs/gpu-memory-hierarchy">存储层次</a>给了从寄存器到 HBM 的鸟瞰；大模型栏的 <a href="/llm/cuda-occupancy">Warp / CTA / 占用率</a>又从写内核的角度算过占用率的账。缺的是执行模型本身的合同：<code>kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;</code> 发出之后，硬件如何把线程折成 warp、把 warp 摆上 SM、按什么规则发射指令。后课的层次、原语、张量核都默认你已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干给的是画面，不是账。同一份核函数，block 尺寸从 64 改到 256，速度差三倍；换一台同代显卡，最优尺寸又不一样。如果只把 block 当「随便填的并行度」，每个尺寸选择都是抽签。缺口因此是：把「线程是虚构的、warp 是实体的」这条 SIMT 直觉，补成一张能预算的表——block 怎么被切分、凭什么被放上某个 SM、放上去之后每一拍发生什么。大模型栏的占用率课给过「怎么算占用率」，本课给的是占用率公式的来路：每一项除数都是一条硬件限制。</p><h3 id="从三层命名到调度原子" tabindex="-1">从三层命名到调度原子 <a class="header-anchor" href="#从三层命名到调度原子" aria-label="Permalink to &quot;从三层命名到调度原子&quot;">​</a></h3><p>grid、block、thread 是程序员的命名；硬件接手的是 block（CTA）。launch 之后，运行时把 block 逐个分给 SM，每个 SM 收一个 block 之前先过资源检查：该 block 每线程的寄存器数乘以线程数不超过 SM 寄存器堆，静态 smem 请求不超过片上余量，常驻线程数不超过上限。检查不过，block 就排队等别的退场。block 内部随即切成 \\(n=\\lceil \\mathrm{blockDim}/32\\rceil\\) 个 warp——不够 32 的零头也占一个 warp，这就是「block 尺寸取 32 的倍数」的由来：零头 warp 里的 lane 空转，白占一个调度名额。</p>',7)),(r(),o(p,null,{default:e(()=>[i(E,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOST%5B%22host%20%E5%8F%91%E5%87%BA%20kernel%20%E5%90%AF%E5%8A%A8%E5%91%BD%E4%BB%A4%EF%BC%8C%E6%8C%87%E5%90%8D%20grid%20%E4%B8%8E%20block%22%5D%20--%3E%20QUEUE%5B%22%E5%91%BD%E4%BB%A4%E8%BF%9B%20stream%20%E9%98%9F%E5%88%97%EF%BC%8Chost%20%E7%AB%8B%E5%8D%B3%E8%BF%94%E5%9B%9E%22%5D%0A%20%20QUEUE%20--%3E%20CHK%5B%22SM%20%E8%B5%84%E6%BA%90%E6%A3%80%E6%9F%A5%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%20%2F%20smem%20%2F%20%E5%B8%B8%E9%A9%BB%E4%B8%8A%E9%99%90%22%5D%0A%20%20CHK%20--%3E%20CTA%5B%22block%20%E6%91%86%E4%B8%8A%20SM%22%5D%0A%20%20CTA%20--%3E%20WARP%5B%22%E5%88%87%20warp%EF%BC%9Aceil(threads%2F32)%22%5D%0A%20%20WARP%20--%3E%20SCHED%5B%22warp%20%E8%B0%83%E5%BA%A6%E5%99%A8%E9%80%90%E6%8B%8D%E5%8F%91%E5%B0%84%E6%8C%87%E4%BB%A4%22%5D%0A%20%20SCHED%20--%3E%20DIV%5B%22%E5%8F%91%E6%95%A3%EF%BC%9A%E4%B8%A4%E6%9D%A1%E8%B7%AF%E5%BE%84%E4%B8%B2%E8%A1%8C%E7%9B%B8%E5%8A%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把资源检查写成预算表，写核之前先估三行。寄存器：A100（sm_80）每 SM 65536 个 32 位寄存器，每线程上限 255；若编译器报 128 个每线程，仅此一项就把常驻压到 512 线程。smem：静态加动态请求一起报。线程上限：sm_80 每 SM 2048。三行取最小，就是该 block 能驻留的份数，也是占用率课里那个公式的除数来源。编译走两级：<code>.cu</code> 先编到 PTX 这个虚拟指令集，驱动再把 PTX 或内嵌的 SASS 装到具体芯片——所以老二进制在新卡上仍能跑（驱动现场编译），但首次启动要付 JIT 的钱。</p><p>launch 的异步语义要当成合同背下来：命令进入 stream 队列后 host 立即返回，错误码也要等到以后某次同步才浮出——这既是性能设计，也是调试课里一切麻烦的源头。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发射的账在调度器上。A100 每个 SM 有四个 warp 调度器，每拍各可发射一条指令；一个 warp 因访存停住时，调度器切到同组的其他 warp。延迟隐藏因此不是魔法，是乘法：常驻 warp 数乘以每 warp 的发射率，要盖得住访存延迟乘访存频度——常驻不够时，盖不住的等待直接变成空拍，这正是占用率检查在执行期的意义。</p><p>Volta 起的独立线程调度把锁步拆掉了：每个 lane 有自己的 PC，配一套收敛栈；发散的分支里，跑完一条路径再跑另一条，落汇合点按栈重组。变化在语义而不在成本：发散的成本从「锁步被破坏」变成「两条路径的周期相加」，\\(t_{\\mathrm{warp}} = t_{\\mathrm{taken}} + t_{\\mathrm{skipped}}\\)。写代码的推论是：分支两侧的长调用照样贵，warp 内「多数投票再统一走」这类技巧（第三课）才有价值。</p><p><span class="marginnote">A100 的账：65536 个寄存器除以每线程 128 个，常驻上限先被压到 512 线程——寄存器密度常常比占用率计算器更早给出瓶颈；<code>-Xptxas -v</code> 的编译输出就是这张表的第一行。</span></p><p><span class="marginnote">数字实例：block 取 100 线程，\\(\\lceil 100/32\\rceil=4\\) 个 warp，第 4 个 warp 只有 4 条活跃 lane——28/32 ≈ 88% 的算力白占调度名额还照付发射周期；取 96 或 128 则整除无零头。同一份核函数仅把 block 从 64 调到 256 就差三倍，正是因为 warp 数与常驻份数一起变了。</span></p><p><span class="marginnote">常见误区：初学者容易以为「if 分支里另一个 warp 的线程也在并行跑」。实际上分支把同一个 warp 的 32 条 lane 拆成两组先后执行，硬件用 mask 关掉不参与的 lane；只有不同 warp 之间才是真并行。所以「if 里做慢调用不影响别的线程」在 warp 内不成立。</span></p>',9)),(r(),o(p,null,{default:e(()=>[i(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20BR%5B%22warp%20%E9%81%87%E5%88%86%E6%94%AF%20cond%22%5D%20--%3E%20SPLIT%5B%22%E6%8C%89%20mask%20%E6%8B%86%E4%B8%A4%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SPLIT%20--%3E%20P1%5B%22%E8%B7%AF%E5%BE%84%20A%20%E6%89%A7%E8%A1%8C%20%E9%9D%9E%20A%20%E7%9A%84%20lane%20%E5%85%B3%E9%97%AD%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E8%B7%AF%E5%BE%84%20B%20%E6%89%A7%E8%A1%8C%20%E9%9D%9E%20B%20%E7%9A%84%20lane%20%E5%85%B3%E9%97%AD%22%5D%0A%20%20P2%20--%3E%20JOIN%5B%22%E5%88%B0%E6%B1%87%E5%90%88%E7%82%B9%E6%8C%89%E6%94%B6%E6%95%9B%E6%A0%88%E9%87%8D%E7%BB%84%22%5D%0A%20%20JOIN%20--%3E%20COST%5B%22%E6%80%BB%E5%91%A8%E6%9C%9F%20%3D%20A%20%E8%B7%AF%E5%BE%84%20%2B%20B%20%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲数据放在哪一层——那是下一课；不进张量核的指令合同——第五课起。占用率高不等于快，<a href="/llm/cuda-occupancy">占用率课</a>已立过这条，本课只补了它的来路。执行模型不承诺任何 warp 间时序：同一 block 内 warp 的推进顺序无定义，任何跨 warp 的协作必须显式同步；拿「通常先启动的先跑」当代价模型，会在换卡或换驱动时变成竞态。也不承诺指令的精确周期数——本课的账是量级与结构，不是时钟级仿真；要证据，profiling 课会给。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>grid/block/thread 是命名，CTA 是调度与占用的原子；block 上 SM 前过寄存器、smem、常驻上限三道检查。</li><li>block 切成 \\(\\lceil \\mathrm{threads}/32\\rceil\\) 个 warp，零头也占一个 warp——block 尺寸取 32 的倍数。</li><li>延迟隐藏是乘法账：常驻 warp 数乘发射率盖住访存等待，盖不住就是空拍。</li><li>Volta 起独立线程调度：每 lane 一份 PC，发散成本是两条路径相加，语义合同落在 mask 参数上。</li><li>launch 异步、错误延迟浮出、PTX 到 SASS 两级编译，都是后课反复用到的合同。</li><li>出处：NVIDIA CUDA C++ Programming Guide「Hardware Implementation」章；Lindholm et al., <em>IEEE Micro</em>, 2008。</li></ul>',4))])}const k=c(s,[["render",B]]);export{_ as __pageData,k as default};
